ROOT=os.path.join(os.path.dirname(__file__),'..','public','beirouti')
L=json.load(open(os.path.join(ROOT,'assets','listings.json')))
DEV=sorted(f[:-4] for f in os.listdir(os.path.join(ROOT,'images','developers')))
PHONE='+971 50 191 1512'; WA='971501911512'; EMAIL='beiroutire@gmail.com'
e=html.escape
NAV=[('About Us','about.html',[]),('Properties','properties.html',[('Off-Plan','off-plan.html'),('Secondary Market','secondary-market.html'),('Developer Projects','developer-projects.html'),('Company Properties','company-properties.html'),('Client Properties','client-properties.html')]),('Developers','developers.html',[]),('Services','services.html',[])]
WAICON='<svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M12 2a10 10 0 0 0-8.6 15.1L2 22l5-1.3A10 10 0 1 0 12 2Zm5.3 14.1c-.2.6-1.3 1.2-1.8 1.2-.5.1-1 .2-3.4-.7-2.9-1.1-4.7-4-4.9-4.2-.1-.2-1.2-1.6-1.2-3s.7-2.1 1-2.4c.3-.3.6-.3.8-.3h.6c.2 0 .4 0 .6.5l.9 2.1c.1.2.1.4 0 .5l-.4.6-.4.4c-.1.1-.3.3-.1.6.2.3.8 1.3 1.7 2.1 1.2 1 2.1 1.3 2.4 1.5.3.1.5.1.6-.1l.9-1c.2-.3.4-.2.6-.1l2 .9c.3.2.5.2.6.4 0 .1 0 .7-.3 1.3Z"/></svg>'
def head(title,desc,pre):
  return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>{e(title)}</title><meta name="description" content="{e(desc)}"><meta property="og:title" content="{e(title)}"><meta property="og:description" content="{e(desc)}"><meta property="og:type" content="website">
<link rel="preconnect" href="https://fonts.googleapis.com"><link href="https://fonts.googleapis.com/css2?family=Cormorant+Garamond:wght@500;600&family=Manrope:wght@400;500;600;700&display=swap" rel="stylesheet">
<link rel="stylesheet" href="{pre}assets/beirouti.css"></head><body>'''
def header(cur,pre):
  items=''
  for t,h,kids in NAV:
    sub=''.join(f'<li><a href="{pre}{kh}">{kt}</a></li>' for kt,kh in kids)
    cls=' class="menu-item-has-children"' if kids else ''
    ac=' aria-current="page"' if h==cur or any(kh==cur for _,kh in kids) else ''
    items+=f'<li{cls}><a href="{pre}{h}"{ac}>{t}</a>'+(f'<ul>{sub}</ul>' if sub else '')+'</li>'
  return f'''<header class="site-header"><div class="wrap"><a class="brand" href="{pre}index.html"><img src="{pre}images/logo.png" alt="Beirouti Real Estate logo"><span>Beirouti<small>Real Estate</small></span></a>
<button class="menu-toggle" aria-label="Open menu" onclick="document.querySelector('.nav').classList.toggle('open')">☰</button>
<nav class="nav" aria-label="Main"><ul>{items}</ul><a class="btn btn-gold nav-cta" href="{pre}contact.html">Contact Us</a></nav></div></header><main>'''
def footer(pre):
  return f'''</main><footer class="site-footer"><div class="wrap"><div class="cols">
<div><img class="footer-logo" src="{pre}images/logo.png" alt="Beirouti Real Estate"><p>Building Trust, Creating Opportunities. Rooted in Abu Dhabi, connecting you to opportunities across the UAE.</p></div>
<div><h4>Properties</h4><ul><li><a href="{pre}off-plan.html">Off-Plan</a></li><li><a href="{pre}secondary-market.html">Secondary Market</a></li><li><a href="{pre}developer-projects.html">Developer Projects</a></li><li><a href="{pre}company-properties.html">Company Properties</a></li><li><a href="{pre}client-properties.html">Client Properties</a></li></ul></div>
<div><h4>Company</h4><ul><li><a href="{pre}about.html">About Us</a></li><li><a href="{pre}services.html">Services</a></li><li><a href="{pre}developers.html">Developers</a></li><li><a href="{pre}contact.html">Contact</a></li></ul></div>
<div><h4>Contact</h4><ul><li>Abu Dhabi, United Arab Emirates</li><li><a href="tel:{PHONE.replace(' ','')}">{PHONE}</a></li><li><a href="mailto:{EMAIL}">{EMAIL}</a></li></ul></div>
</div><div class="legal"><span>© 2026 Beirouti Real Estate. Licensed in Abu Dhabi.</span><span>Your Property, Our Priority</span></div></div></footer>
<a class="wa-float" href="https://wa.me/{WA}" aria-label="Chat on WhatsApp">{WAICON}</a>
<script>document.querySelectorAll('[data-filter]').forEach(function(g){{g.addEventListener('click',function(ev){{var b=ev.target.closest('.chip');if(!b)return;g.querySelectorAll('.chip').forEach(function(c){{c.classList.remove('on')}});b.classList.add('on');var v=b.dataset.v,n=0;document.querySelectorAll('#'+g.dataset.filter+' .card').forEach(function(c){{var s=v==='all'||c.dataset.tags.split(' ').indexOf(v)>-1;c.style.display=s?'':'none';if(s)n++}});}})}});
document.querySelectorAll('.thumbs img').forEach(function(t){{t.onclick=function(){{document.querySelector('.gallery-main img').src=t.src;document.querySelectorAll('.thumbs img').forEach(function(x){{x.classList.remove('on')}});t.classList.add('on')}}}});</script></body></html>'''
LBL={'off-plan':'Off-Plan','secondary':'Secondary Market','developer':'Developer Project','company':'Company Property','client':'Client Property','sale':'For Sale','rent':'For Rent'}
def card(p,pre):
  tags=f"{p['market']} {p['source']} {p['purpose']}"
  return f'''<a class="card" href="{pre}property/{p['slug']}.html" data-tags="{tags}"><div class="card-media"><img loading="lazy" src="{pre}images/{p['images'][0]}" alt="{e(p['title'])}"><div class="tags"><span class="tag solid">{LBL[p['market']]}</span><span class="tag">{LBL[p['purpose']]}</span></div></div>
<div class="card-body"><span class="loc">{e(p['location'])}</span><h3>{e(p['title'])}</h3><span class="loc">{LBL[p['source']]}{' · '+e(p['developer']) if p['developer'] else ''}</span><span class="price">{e(p['price'])}</span><div class="specs"><span>{e(p['type'])}</span><span>{e(p['beds'])} Beds</span><span>{e(p['size'])}</span></div></div></a>'''
def grid(items,pre,gid='list',filters=True):
  f=''
  if filters:
    f=f'<div class="filters" data-filter="{gid}">'+''.join(f'<button class="chip{" on" if v=="all" else ""}" data-v="{v}">{t}</button>' for v,t in [('all','All'),('off-plan','Off-Plan'),('secondary','Secondary Market'),('sale','For Sale'),('rent','For Rent')])+'</div>'
  body=''.join(card(p,pre) for p in items) or '<div class="empty">New listings coming soon.</div>'
  return f+f'<div class="grid g3" id="{gid}">{body}</div>'
def page_hero(eyebrow,title,text,crumb,pre):
  return f'<section class="page-hero"><div class="wrap"><div class="crumbs"><a href="{pre}index.html">Home</a> / {crumb}</div><div class="eyebrow">{eyebrow}</div><h1>{title}</h1><p>{text}</p></div></section>'
def marquee(pre):
  imgs=''.join(f'<img src="{pre}images/developers/{d}.jpg" alt="{d.replace("-"," ").title()} logo">' for d in DEV)
  return f'<div class="marquee"><div class="marquee-track">{imgs}{imgs}</div></div>'
def cta(pre):
  return f'<section class="section"><div class="wrap"><div class="cta"><div class="eyebrow" style="justify-content:center">Speak to our team</div><h2>Find the right property, <span class="gold">with people you trust</span></h2><p>Tell us what you are looking for and we will reply quickly with suitable options across Abu Dhabi, Dubai and the wider UAE.</p><a class="btn btn-gold" href="https://wa.me/{WA}">WhatsApp Us</a> <a class="btn btn-line" href="{pre}contact.html">Send an Enquiry</a></div></div></section>'
def write(name,title,desc,body,cur=None,pre=''):
  p=os.path.join(ROOT,name); os.makedirs(os.path.dirname(p),exist_ok=True)
  open(p,'w').write(head(title,desc,pre)+header(cur or name,pre)+body+footer(pre))
